nextflow_process {

    name "Test Process WHATSHAP_STATS"
    script "../main.nf"
    process "WHATSHAP_STATS"

    tag "modules"
    tag "modules_nfcore"
    tag "whatshap"
    tag "whatshap/stats"

    test("homo_sapiens - all_output - vcf") {

        when {
            process {
                """

                input[0] = [
                    [ id:'test_sample' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz', checkIfExists: true),
                ]
                input[1] = true
                input[2] = true
                input[3] = true

                """
            }
        }

        then {

            assertAll(
                { assert process.success                                                                 },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith("versions")},
                process.out).match()}

            )

        }

    }
    test("homo_sapiens - tsv_output - vcf") {

        when {
            process {
                """

                input[0] = [
                    [ id:'test_sample' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz', checkIfExists: true),
                ]
                input[1] = true
                input[2] = false
                input[3] = false

                """
            }
        }

        then {

            assertAll(
                { assert process.success                                                                 },
                { assert snapshot(process.out.findAll { key, val -> key.startsWith("versions")}, process.out).match() },

            )

        }

    }

    test("homo_sapiens - vcf -stub") {

        options "-stub"

        when {
            process {
                """

                input[0] = [
                    [ id:'test_sample' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz', checkIfExists: true),
                ]
                input[1] = true
                input[2] = true
                input[3] = true
                """
            }
        }

        then {

            assertAll(
                { assert process.success                                                                 },
                { assert snapshot(
                    process.out.findAll { key, val -> key.startsWith("versions")},
                    process.out
                ).match() },
            )

        }

    }

}
